use std::ops::{Add, AddAssign, Mul, Neg, Sub};
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct Money(i64);

solution.solution.rs:
use std::fmt;
use std::ops::{Add, AddAssign, Mul, Neg, Sub};
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct Money(i64);

impl Add for Money {
    type Output = Money;
    fn add(self, o: Money) -> Money {
        Money(self.0 + o.0)
    }
}

impl Sub for Money {
    type Output = Money;
    fn sub(self, o: Money) -> Money {
        Money(self.0 - o.0)
    }
}

impl Neg for Money {
    type Output = Money;
    fn neg(self) -> Money {
        Money(-self.0)
    }
}

impl AddAssign for Money {
    fn add_assign(&mut self, o: Money) {
        self.0 += o.0;
    }
}

impl Mul<i64> for Money {
    type Output = Money;
    fn mul(self, k: i64) -> Money {
        Money(self.0 * k)
    }
}

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let sign = if self.0 < 0 { "-" } else { "" };
        let p = self.0.abs();
        write!(f, "{sign}£{}.{:02}", p / 100, p % 100)
    }
}

impl FromStr for Money {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let (neg, rest) = match s.strip_prefix('-') {
            Some(r) => (true, r),
            None => (false, s),
        };
        let (pounds, pence) = match rest.split_once('.') {
            Some((p, d)) => (p, d),
            None => (rest, ""),
        };
        let ok_pounds = !pounds.is_empty() && pounds.chars().all(|c| c.is_ascii_digit());
        let ok_pence = pence.len() <= 2 && pence.chars().all(|c| c.is_ascii_digit()) && !(rest.contains('.') && pence.is_empty());
        if !ok_pounds || !ok_pence {
            return Err(format!("not an amount: {s:?}"));
        }
        let whole: i64 = pounds.parse().map_err(|_| format!("not an amount: {s:?}"))?;
        let frac: i64 = match pence.len() {
            0 => 0,
            1 => pence.parse::<i64>().unwrap() * 10,
            _ => pence.parse::<i64>().unwrap(),
        };
        let total = whole * 100 + frac;
        Ok(Money(if neg { -total } else { total }))
    }
}

unitTests:
test("operators", || {
    let a = Money(1250);
    let b = Money(375);
    check_eq(a + b, Money(1625));
    check_eq(a - b, Money(875));
    check_eq(-b, Money(-375));
    check_eq(b * 3, Money(1125));
    let mut t = Money(0);
    t += a;
    t += b;
    check_eq(t, Money(1625));
    check(a > b);
});

test("display", || {
    check_eq(Money(1234).to_string(), "£12.34");
    check_eq(Money(5).to_string(), "£0.05");
    check_eq(Money(-150).to_string(), "-£1.50");
});

test("parse", || {
    check_eq("12.34".parse::<Money>(), Ok(Money(1234)));
    check_eq("12".parse::<Money>(), Ok(Money(1200)));
    check_eq("-1.5".parse::<Money>(), Ok(Money(-150)));
    check_eq("0.05".parse::<Money>(), Ok(Money(5)));
    for bad in ["", "abc", "1.234", "1.", ".5", "1,50", "--1"] {
        check(bad.parse::<Money>().is_err());
    }
});

